"""150 TOEFL ITP Reading items (Packs 1-3: 5 academic passages x 10 Qs each = 50 per pack)."""

from pack_schema_helpers import rotated_mcq


def _expand_reading_pack(pack_num: int, passages_spec: list) -> tuple[list[dict], list[dict]]:
    passages = []
    questions = []
    q_idx = 91
    for p_ord, (pid_sfx, title, body, qlist) in enumerate(passages_spec, start=1):
        pid = f"ITP0{pack_num}-{pid_sfx}"
        assert len(qlist) == 10, f"{pid}: expected 10 reading questions, got {len(qlist)}"
        passages.append({
            "id": pid,
            "title": title,
            "body": body,
            "readingOrder": p_ord,
        })
        for sub_i, (qtext, opts, cidx, mod, diff, exp) in enumerate(qlist, start=1):
            qid = f"ITP-L1-0{pack_num}-Q{q_idx:03d}"
            full_prompt = f"Passage {p_ord} ('{title}') — Q{sub_i}/10: {qtext}"
            questions.append(
                rotated_mcq(qid, "READING", full_prompt, opts, cidx, exp, mod, diff, seed=pack_num * 13 + q_idx, passage_id=pid),
            )
            q_idx += 1
    assert len(questions) == 50
    return passages, questions


